INSERT INTO public.books(slug,title,author,genre,description,synopsis,cover_url,featured,source,discussion_prompts) VALUES ('a-thousand-little-cuts','A Thousand Little Cuts','Max E. Carlson','Mystery','A traumatized psychologist, a detective, and a priest unravel a mysterious woman’s lost memory as a rising evil threatens them all.','Brock Williams is a psychologist in Boulder, Colorado. He suffers from PTSD as a result of a violent encounter with a former patient who nearly killed him. His diagnosis hinders himself personally as well as professionally. His close friend, Luke, a detective with the county sheriff''s department, finds a woman on the street suffering from a fugue state, with no recollection of her personal identity or self. She seeks psychotherapy to recover and ends up as Brock''s patient. She has flashes which, at first, seem meaningless, but later are determined to be clues explaining why she entered the amnesia–fugue state and traveled from her home to Boulder, Colorado. The fugue lady, unknown even to her, has lost her personal memory in order to prevent a future evil event from happening. As Brock and Luke slowly unravel the puzzle, help is sought from Father Uriah, a Catholic priest, to suppress the rising evil, an evil that snares all of them into various traps and dilemmas. In the process, Brock''s PTSD is tested to its breaking point as unknown relationships surface placing him and several other characters in deadly danger. It will take their combined efforts to have any chance of uncovering the surprising relationships involved and the emerging evil, let alone prevent it from happening.','/__l5e/assets-v1/0ead0c7b-742a-4b21-aca1-cb1dec2d8126/a-thousand-little-cuts.png',true,'author','["How might Brock’s PTSD shape the trust and boundaries in his work with the woman suffering from a fugue state?","The synopsis suggests that losing memory may prevent a future evil event. How does this premise complicate the relationship between memory and protection?","What different perspectives do psychotherapy, detective work, and Father Uriah’s faith bring to the mystery?","As the woman’s flashes become clues, how would you distinguish a meaningful pattern from a misleading connection without guessing the ending?"]');
INSERT INTO public.contributions(book_id,kind,title,body,source) SELECT id,'discussion','Memory as protection, memory as a clue','The supplied synopsis describes a woman whose missing memory may prevent a future evil event. What questions does that raise about identity and protection? Keep your reflections grounded in the premise and avoid revealing an ending.','editorial' FROM public.books WHERE slug='a-thousand-little-cuts';